import{_ as s,o as a,c as l,a as e}from"./app.83c7065c.js";const o="/assets/event-bubbling.1c7b6617.png",n="/assets/performance-panel.1a4e7fc2.jpg",f=JSON.parse('{"title":"scroll事件踩坑记录","description":"","frontmatter":{"title":"scroll事件踩坑记录","date":"2020-05-25"},"headers":[],"relativePath":"2020/scroll-event-pitfalls.md","lastUpdated":1786184870000}'),p={name:"2020/scroll-event-pitfalls.md"},r=e('<h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-hidden="true">#</a></h3><p>使用Vue重构一个jQuery的H5/PC页面，一个列表组件实现滚动加载更多的时候踩了个坑。</p><h3 id="现象" tabindex="-1">现象 <a class="header-anchor" href="#现象" aria-hidden="true">#</a></h3><ul><li><p>没有触发滚动 开始是把滚动事件绑定在列表组件的父级元素，然后发现无论如何都无法触发滚动事件</p></li><li><p>实现父元素滚动的布局导致了刘海屏下的一个兼容性bug 让html和body的高度都为屏高，父元素继承body高度也撑满body，监听父元素的滚动事件。</p></li></ul><p>这个布局方式导致safe-area区域不能跟随滚动消失，始终占据了屏幕的底部位置</p><h3 id="原因" tabindex="-1">原因 <a class="header-anchor" href="#原因" aria-hidden="true">#</a></h3><p>先说第一个现象的原因</p><h4 id="scroll事件冒泡原理" tabindex="-1">scroll事件冒泡原理 <a class="header-anchor" href="#scroll事件冒泡原理" aria-hidden="true">#</a></h4><ul><li><p>一般页面元素的scroll事件和普通事件不同，没有事件冒泡过程</p><p><img src="'+o+'" alt="event-bubbling"></p><p>也就是在上图的4就结束了，只经过<code>事件捕获 -&gt; 事件触发</code>，没有事件冒泡的过程，之前监听父元素的事件委托做法是行不通的。</p></li><li><p>来自document元素的scroll事件可以冒泡</p><p>由于其自身已经是顶层元素了，所以这个场景下事件冒泡与否已经失去了意义。</p></li><li><p>具体可以参考<a href="https://ayase.moe/2018/11/20/scroll-event/" target="_blank" rel="noreferrer">这篇文章</a>，写的很清楚</p></li></ul><h3 id="如何处理scroll事件" tabindex="-1">如何处理scroll事件 <a class="header-anchor" href="#如何处理scroll事件" aria-hidden="true">#</a></h3><h4 id="确认监听scroll事件目标元素" tabindex="-1">确认监听scroll事件目标元素 <a class="header-anchor" href="#确认监听scroll事件目标元素" aria-hidden="true">#</a></h4><p>首先要明确开发功能的目标是在那个元素监听scroll事件。</p><p>比如上面提到safe-area的bug，要让safe-area跟随scroll事件收起和展开，需要监听document元素的滚动事件。</p><p>但是其他情况，也许不需要在document元素上监听。比如网页内有个固定高度的table元素，要监听他的内部滚动事件，可以只监听table的scroll事件。</p><p>具体监听哪个元素的scroll事件，要根据功能目标来确定。这是思考的出发点。</p><h4 id="如何判断绑定正确或错误" tabindex="-1">如何判断绑定正确或错误 <a class="header-anchor" href="#如何判断绑定正确或错误" aria-hidden="true">#</a></h4><p>在明确监听元素之后，再来观察是否监听到了正确的元素。可以通过以下方法来判断（此处以chrome为例子）：</p><ul><li><code>devTool - Performance</code>，点击<code>Record</code>开始录制</li><li>滚动页面</li><li>结束录制</li><li>点击<code>Event Log</code>，搜索框内输入scroll，在最右侧就能看到scroll事件绑定的元素</li><li>确认绑定元素是否为目标元素即可</li></ul><p>如下图所示：</p><p><img src="'+n+`" alt="performance-panel"></p><h4 id="绑定document的处理" tabindex="-1">绑定document的处理 <a class="header-anchor" href="#绑定document的处理" aria-hidden="true">#</a></h4><p>需要在Vue的生命周期钩子函数中绑定和解绑scroll事件，考虑到H5页面，因此追加了passive属性</p><div class="language-javascript"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#89DDFF;">...</span></span>
<span class="line"><span style="color:#82AAFF;">mounted</span><span style="color:#A6ACCD;">()</span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#F07178;">    </span><span style="color:#A6ACCD;">window</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">addEventListener</span><span style="color:#F07178;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">scroll</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">,</span><span style="color:#F07178;"> </span><span style="color:#89DDFF;">this.</span><span style="color:#A6ACCD;">handleScroll</span><span style="color:#89DDFF;">,</span><span style="color:#F07178;"> </span><span style="color:#89DDFF;">{</span><span style="color:#F07178;">passive</span><span style="color:#89DDFF;">:</span><span style="color:#F07178;"> </span><span style="color:#FF9CAC;">true</span><span style="color:#89DDFF;">}</span><span style="color:#F07178;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">},</span></span>
<span class="line"><span style="color:#82AAFF;">destroyed</span><span style="color:#A6ACCD;">()</span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#F07178;">    </span><span style="color:#A6ACCD;">window</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">addEventListener</span><span style="color:#F07178;">(</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">scroll</span><span style="color:#89DDFF;">&#39;</span><span style="color:#89DDFF;">,</span><span style="color:#F07178;"> </span><span style="color:#89DDFF;">this.</span><span style="color:#A6ACCD;">handleScroll</span><span style="color:#89DDFF;">,</span><span style="color:#F07178;"> </span><span style="color:#89DDFF;">{</span><span style="color:#F07178;">passive</span><span style="color:#89DDFF;">:</span><span style="color:#F07178;"> </span><span style="color:#FF9CAC;">true</span><span style="color:#89DDFF;">}</span><span style="color:#F07178;">)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"></span></code></pre></div><h4 id="绑定页面元素的处理" tabindex="-1">绑定页面元素的处理 <a class="header-anchor" href="#绑定页面元素的处理" aria-hidden="true">#</a></h4><p>可以在目标元素上绑定scroll事件，同时使用passive属性提高移动端滚动体验</p><div class="language-html"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#89DDFF;">&lt;</span><span style="color:#F07178;">div</span><span style="color:#89DDFF;"> </span><span style="color:#C792EA;">@scroll.passive</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">handleScroll</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"></span></code></pre></div><p>元素对应的CSS中要增加<code>overflow-y: scroll</code>或者<code>overflow-y: auto</code>的设置</p><h3 id="其他兼容性处理" tabindex="-1">其他兼容性处理 <a class="header-anchor" href="#其他兼容性处理" aria-hidden="true">#</a></h3><h4 id="webkit-overflow-scrolling-touch" tabindex="-1">-webkit-overflow-scrolling: touch <a class="header-anchor" href="#webkit-overflow-scrolling-touch" aria-hidden="true">#</a></h4><p>对iOS来说，为了避免滚动卡顿，还需要在滚动的目标元素上设置<code>-webkit-overflow-scrolling: touch</code>，开启硬件加速，提升用户体验</p><p>Done</p>`,31),c=[r];function t(i,d,h,F,y,D){return a(),l("div",null,c)}const b=s(p,[["render",t]]);export{f as __pageData,b as default};
